abstract class Shape {
    abstract double area();
}
class Circle extends Shape {
    private final double r; Circle(double r) { this.r = r; }
    double area() { return Math.PI * r * r; }
}
class Square extends Shape {
    private final double side; Square(double side) { this.side = side; }
    double area() { return side * side; }
}
public class ShapeAbstractionDemo {
    public static void main(String[] args) {
        Shape[] shapes = { new Circle(1), new Square(2) };
        double total = 0; for (Shape shape : shapes) total += shape.area();
        System.out.printf("%.2f%n", total);
    }
}
